mapper.select:
SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, TB.* FROM ( SELECT A.MANAGER_ID, A.MANAGER_NAME, A.USE_YN, A.PART_ID, C.PART_NM, A.EMP_NO, A.MANAGER_STATUS, A.ROLE_ID, R.ROLE_NAME, A.CENTER_ID, A.MANAGER_EMAIL, A.MANAGER_TEL, TO_CHAR(A.LAST_UPDT_PNTTM, 'YYYY-MM-DD HH24:MI') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM tb_managerinfo A LEFT JOIN tb_partinfo C ON A.PART_ID = C.PART_ID LEFT JOIN tb_roleinfo R ON A.ROLE_ID = R.ROLE_ID WHERE 1=1
AND A.PART_ID IN ( WITH RECURSIVE cte AS ( SELECT PART_ID FROM tb_partinfo WHERE PART_ID = #{params.partId} UNION SELECT P.PART_ID FROM tb_partinfo P JOIN cte ON P.PARENT_PART_ID = cte.PART_ID ) SELECT PART_ID FROM cte )
AND A.CENTER_ID = #{params.loginCenterId}
AND A.MANAGER_ID LIKE CONCAT('%', #{params.searchKeyword}, '%')
AND (A.MANAGER_ID LIKE CONCAT('%', #{params.searchKeyword}, '%') OR A.MANAGER_NAME LIKE CONCAT('%', #{params.searchKeyword}, '%'))
AND A.ROLE_ID = #{params.searchRoleId}
AND A.PART_ID = #{params.searchPartId}
AND A.USE_YN = #{params.searchUseYn}
ORDER BY
A.MANAGER_ID ${sortDir} A.MANAGER_NAME ${sortDir}, A.MANAGER_ID ASC C.PART_NM ${sortDir}, A.MANAGER_ID ASC R.ROLE_NAME ${sortDir}, A.MANAGER_ID ASC A.CENTER_ID ${sortDir}, A.MANAGER_ID ASC A.MANAGER_STATUS ${sortDir}, A.MANAGER_ID ASC A.USE_YN ${sortDir}, A.MANAGER_ID ASC A.MANAGER_EMAIL ${sortDir}, A.MANAGER_ID ASC A.MANAGER_TEL ${sortDir}, A.MANAGER_ID ASC A.LAST_UPDT_PNTTM ${sortDir}, A.MANAGER_ID ASC A.MANAGER_ID ASC
) TB LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

SELECT COUNT(*)
FROM tb_managerinfo
WHERE MANAGER_ID = #{managerId}

SELECT COUNT(*)
FROM tb_managerinfo
WHERE MANAGER_ID = #{params.managerId}
  AND MANAGER_PASSWORD = #{params.managerPassword}
